const payload = $input.first()?.json ?? {};
const models = Array.isArray(payload.data) ? payload.data : (Array.isArray(payload.models) ? payload.models : []);
const ids = models.map(m => m?.id).filter(Boolean);
const firstMatch = (patterns, excluded = []) => {
  for (const pattern of patterns) {
    const found = ids.find(id => pattern.test(id) && !excluded.includes(id));
    if (found) return found;
  }
  return null;
};
const fast = firstMatch([/Qwen3[-_/].*30B/i, /Qwen.*30B/i, /Qwen.*14B/i, /Qwen/i]);
const strong = firstMatch([/Qwen3[-_/].*235B/i, /Qwen.*235B/i, /Qwen.*72B/i, /Qwen/i], [fast]);
const audit = firstMatch([/openai\/gpt-oss-120b/i, /openai\//i, /deepseek/i, /mistral/i, /llama/i], [fast, strong]);
if (!fast || !strong || !audit) {
  throw new Error(`MODEL_ROLE_SELECTION_FAILED available=${ids.length} fast=${fast} strong=${strong} audit=${audit}`);
}
return [{json:{fast_model:fast,strong_model:strong,audit_model:audit,available_model_count:ids.length,selected_at:new Date().toISOString()}}];

const model = $json.fast_model;
const request = {
  model,
  messages: [
    { role: 'system', content: 'Return only JSON matching the supplied schema.' },
    { role: 'user', content: 'Classify the next action for an idea with no confirmed customer. The only valid route is ASK_FOUNDER.' }
  ],
  temperature: 0,
  max_tokens: 80,
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'blueprint_route_test',
      strict: true,
      schema: {
        type: 'object',
        properties: {
          route: { type: 'string', enum: ['ASK_FOUNDER'] },
          confidence: { type: 'number', minimum: 0, maximum: 1 }
        },
        required: ['route', 'confidence'],
        additionalProperties: false
      }
    }
  }
};
return [{ json: { request } }];

